ack=unit('A022',s,'Concept ACK, modulo the following',role='context',speech='reported_action',rationale='Qualified conceptual acknowledgment of the broader PR, not a new prescription.')
quote='I think we should either (a) recommend the option not be used and mark it deprecated; or (b) not mark it deprecated, and leave it up to the user to decide whether to use the option, without making any particular recommendation; and not try (c) some other option to split the non-existent difference. If it were just up to me, I\'d choose (b) over (a), but it\'s not a terribly strong opinion.'
orig=unit('A023','32714-011',quote,role='context',speech='proposed',rationale='Supporting context outside focal extraction scope: preserves the complete original compound proposal solely as the endpoint of quotation and response links. Its context record function does not assert that the quoted content lacks prescriptions.')
rep=unit('A024',s,quote,role='quotation',speech='proposed',quotation='repeated',rationale='Exact repetition of ajtowns\'s supplied compound recommendation; not a new proposal by jonatack.')
agree=unit('A025',s,'Agree with @ajtowns.',role='context',speech='reported_action',rationale='Jonatack\'s own explicit endorsement of the immediately quoted technical alternatives, distinct from the repeated text. Assent to this proposal is not recognition of an obligation or a repository norm.')
rel(rep,orig,'quotes',[ev(s,quote),ev('32714-011',quote)],'The full quoted wording, including alternatives, negation, and weak preference, occurs in the supporting source.')
rel(orig,agree,'uptake',[ev(s,quote),ev(s,'Agree with @ajtowns.')],'An exact attributed quotation followed by explicit agreement establishes a proposal-specific endorsement response, not adoption or expectation recognition.')
